import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火山旅","description":"周易折中 - 火山旅","frontmatter":{"title":"火山旅","description":"周易折中 - 火山旅"},"headers":[],"relativePath":"classics/zhezhong/062.md","filePath":"classics/zhezhong/062.md"}'),h={name:"classics/zhezhong/062.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="火山旅" tabindex="-1">火山旅 <a class="header-anchor" href="#火山旅" aria-label="Permalink to “火山旅”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈旅序卦〉：“《豐》大也，窮大者必失其居，故受之以《旅》。《豐》盛，至於窮極，則必失其所安，《旅》所以次《豐》也。為卦離上艮下，山止而不遷，火行而不居，違去而不處之象，故為《旅》也。又麗乎外，亦《旅》之象。”</p><p>旅：小亨，旅貞吉</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>旅，羈旅也。山止於下，火炎於上，為去其所止而不處之象，故為旅。以六五得中於外而順乎上下之二陽，艮止而離麗於明，故其佔可以小亨。而能守其旅之貞，則吉。旅非常居，若可苟者，然道無不在，故自有其正，不可須臾離也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>以卦才言也。如卦之才可以小亨，得旅之貞正而吉也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：在旅而亨，亨之小者也。然事有小大，道無不在。大亨固利於貞，不可以亨之小而失其貞也。正道果可須臾離哉？</li></ul><p>象曰：山上有火，旅。君子以明慎用刑而不留獄</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>愼刑如山，不留如火。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>火之在高，明無不照。君子觀明照之象，則以明慎用刑。明不可恃，故戒於慎。明而止亦慎，象觀火行不處之象，則不留獄。獄者不得已而設，民有罪而入，豈可留滯淹久也？</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：火在山上，逐草而行，勢不久留，故為旅象。又上下二體，艮止離明，故君子象此以明察審慎用刑，而不稽留獄訟。</p></li><li><p>項氏安世曰 ：山非火之所留也，野燒延緣過之而已，故名之曰旅，而象之以不留獄。</p></li><li><p>趙氏汝梅曰 ：火煬則宅於灶，冶則宅於爐，在山則野燒之暫，猶旅寓耳，故為旅之象。離虛為明，艮止為謹，君子體之明謹於用刑而不留獄。蓋獄者人之所旅也，不留獄不使久處其中也。用刑固貴於明，然明者未必謹，謹者或留獄。明矣謹矣而淹延不決，雖明猶暗也，雖謹反害也。</p></li><li><p>張氏淸子曰 ：明則無遁情，慎則無濫罰。明慎既盡，斷決隨之。聖人取象於旅，正恐其留獄也。</p></li></ul><p>彖曰：旅，小亨；柔得中乎外而順乎剛，止而麗乎明，是以小亨。旅貞吉也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體、卦德釋卦辭</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>六上居五，柔得中乎外也；麗乎上下之剛，順乎剛也；下艮止，上離麗，止而麗於明也。柔順而得在外之中，所止能麗於明，是以小亨，得旅之貞正而吉也。旅困之時，非陽剛中正有助於下，不能致大亨也。所謂“得在外之中”，中非一揆，旅有旅之中也。止麗於明，則不失時宜，然後得處旅之道。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏宗傳曰 ：用剛非旅道也，故莫尚乎用柔。然柔不可過也，故莫尚乎得中。以六居五，得中位而屬外體，麗乎二剛之間，故曰“柔得中乎外而順乎剛”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>處旅之道，審幾度勢，貴於明也。待人接物，亦貴於明也。然明不可以獨用，故必以止靜為本，而明麗焉。與晉、睽之主於順說者同。</p><p>旅之時義大矣哉</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>旅之時為難處</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>天下之事，當隨時各適其宜，而旅為難處，故稱其時義之大。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>俞氏琰曰 ：旅之時最難處，旅之義不可不知。葢其亨雖小，其時義則大。聖人小其亨而大其時義，非大旅也，大其處旅之道也。</p></li><li><p>錢氏一本曰 ：難處者，旅之時；難盡者，旅之義。或以旅興，或以旅䘮，所闗甚大。</p></li></ul><p>初六：旅瑣瑣，斯其所取災</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>當旅之時，以陰柔居下位，故其象佔如此。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>六以陰柔在旅之時，處於卑下，是柔弱之人處旅困而在卑賤，所存汙下者也。志卑之人既處旅困，鄙猥瑣細，無所不至，乃其所以致侮辱取災咎也。瑣瑣，猥細之狀。當旅困之時，才質如是，上雖有援，無能為也。四陽性而離體，亦非就下者也。又在旅與他卦為大臣之位者異矣。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏應麟曰 ：《旅》初六“所其所取災”，王輔嗣注云，為斯賤之役，唐郭京謂“斯”合作“㒋”。愚按後漢左雄傳“職斯祿薄”，注云：“斯，賤也”。 不必改“㒋”字。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>易中初爻多取童稚小子之象，在旅則童僕之象，王氏之說是也。</p><p>象曰：旅瑣瑣，志窮災也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>志意窮迫，益自取災也。災眚對言，則有分；獨言則謂災患耳。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>谷氏家傑曰 ：爻賤其行，象鄙其志。</p></li><li><p>楊氏啟新曰 ：窮不是困窮侷促猥陋之義，而是指志向的窮盡和失落，由此導致的災難。</p></li></ul><p>六二：旅即次，懷其資，得童僕貞</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>即次則安，懷資則裕，得其童僕之貞信則無欺而有賴。旅之最吉者也。二有柔順中正之德，故其象佔如此。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二有柔順中正之德。柔順則眾與之，中正則處不失當，故能保其所有。童僕亦盡其忠信，雖不若五有文明之德、上下之助，亦處旅之善者也。次舎，旅所安也；財貨，旅所資也；童僕，旅所賴也。得就次舎，懷蓄其資財，又得童僕之貞良，旅之善也。柔弱在下者，童也；強壯處外者，僕也。二柔順中正，故得內外之心。在旅所親比者，童僕也。不雲吉者，旅寓之際，得免於災厲則已善矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰 ：旅中不能無賴乎童僕之用，亦多不免乎童僕之欺。惟得其貞信者，則無欺而有賴。</p></li><li><p>趙氏玉泉曰 ：二處旅而有柔順中正之德，則內不失己而已無不安，外不失人而人無不與。幾旅之所恃以不可無者，皆有以全之也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>二得位得中，故曰“即次懷資”，與九四之“旅處而得其資斧”者異矣。下有初六比之，故曰“得童僕”，與九三之“喪其童僕”者異矣。在初則為童僕之瑣瑣者，自二視之，則為童僕之貞者，義不相害也。</p><p>象曰：得童僕貞，終無尤也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>羈旅之人所賴者童僕也，既得童僕之忠貞，終無尤悔矣。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：既得童僕，然後即次懷資，皆無所失，故終無尤。</li></ul><p>九三：旅焚其次，喪其童僕貞，厲</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>過剛不中，居下之上，故其象佔如此。喪其童僕，則不止於失其心矣，故“貞”字連下句為義。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>處旅之道，以柔順謙下為先。三剛而不中，又居下體之上，與艮之上有自高之象。在旅而過剛自高，致困災之道也。自高則不順於上，故上不與而焚其次，失所安也。上離為焚象，過剛則暴下，故下離而喪其童僕之貞信，謂失其心也。如此，則危厲之道也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>潘氏夢旗曰 ：居剛而用剛，平時猶不可，況旅乎？以此與下“焚次喪僕”，固其宜也。九三以剛居下體之上，則焚次；上九以剛居上體之上，則焚巢。位愈高，剛愈亢，則禍愈深矣。</p></li><li><p>丘氏富國曰 ：九三爻辭全與二反。二即次而三焚，二得童僕而三喪。二之貞無尤，而三之貞則厲者，二柔順得中，三過剛不中故也。過剛豈處旅之道哉？</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>三得位，故亦有即次之象，以其過剛，故焚之也。六爻惟二三言次，得位故也。</p><p>象曰：旅焚其次，亦以傷矣；以旅與下，其義喪也</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>以旅之時而與下之道如此，義當喪也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>旅焚失其次舍，亦以困傷矣。以旅之時而與下之道如此，義當喪也。在旅而以過剛自高待下，必喪其忠貞，謂失其心也。在旅而失其童僕之心，為可危也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>郭氏雍曰 ：九三剛而不中，故不能安旅，失其所安亦可傷矣。以剛暴之才而以旅道居童僕，宜其失眾心而喪也。夫旅豈與人之道哉？君子自厚而已，故終無以旅與下之事。</p></li><li><p>王氏宗傳曰 ：既已有焚其次之傷矣，而又喪其童僕焉，此暴厲之過也。夫旅親寡之時也，朝夕之所與者童僕而已爾，豈可以旅視之也？九三以旅視乎下，則彼童僕也，亦必以旅視乎上矣，其能久留乎？故曰其義喪也。</p></li><li><p>黃氏淳耀曰 ：下即童僕，以旅與下者，謂視童僕如旅人也。焚次而失其身所依庇，亦已傷而不安矣，況又喪其童僕乎？然非童僕之無良也，當旅時而與下之道刻薄寡恩，直若旅人然，宜不得其心力，義當喪也，將誰咎哉？</p></li></ul><p>九四：旅於處，得其資斧，我心不快</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以陽居陰，處上之下，用柔能下，故其象佔如此。然非其正位，又上無剛陽之與，下唯陰柔之應，故其心有所不快也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四陽剛雖不居中，而處柔在上體之下，有用柔能下之象，得旅之宜也。以剛明之才，為五所與，為初所應，在旅之善者也。然四非正位，故雖得其處止，不若二之就次舎也。有剛明之才，為上下所與，乃旅而得貨財之資、器用之利也。雖在旅為善，然上無剛陽之與，下唯陰柔之應，故不能伸其才、行其志，其心不快也。雲“我”者，據四而言。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><p>蔣氏悌生曰：凡卦爻，陽剛皆勝陰柔，惟旅卦不然。二五皆以柔順得吉，三上皆以陽剛致兇。六爻中，六五最善，二次之，上九最兇，三再次之。九四雖得其處，姑足以安其身而已，豈得盡遂其志？</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>四居位非正，故不曰“即次”而曰“於處”。在旅而處多懼之地，故雖得資（與六二同），而未免加斧以自防衛。其未忘戒心可知，安得快然而安樂乎？</p><p>象曰：旅於處，未得位也；得其資斧，心未快也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>四以近君為當位，在旅五不取君義，故四為未得位也。然則以九居四，不正為有咎矣。曰以剛居柔，旅之宜也。九以剛明之才，欲得時而行其志，故雖得資斧於旅為善，其心志未快也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>黃氏淳耀曰 ：資斧，防患之物，得其資斧不過有以自防，故曰心未快也。</li></ul><p>六五：射雉一矢亡，終以譽命</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>雉，文明之物，離之象也。六五柔順文明，又得中道，為離之主，故得此爻者為射雉之象。雖不無亡矢之費，而所喪不多，終有譽命也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五有文明柔順之德，處得中道而上下與之，處旅之至善者也。人之處旅，能合文明之道，可謂善矣。羈旅之人，動而或失，則困辱隨之；動而無失，然後為善。離為雉，文明之物。射雉，謂取則於文明之道而必合，如射雉一矢而亡之，無不中，則終能致譽命也。譽，令聞也；命，福祿也。五居文明之位，有文明之德，故動必中文明之道也。五君位，人君無旅，旅則失位，故不取君義。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱氏震曰 ：五在旅卦不取君象，有文明之德，則令譽升聞而爵命之矣。</p></li><li><p>朱子語類雲 ：亡字正如秦無亡矢遺鏃之“亡”，不是如伊川之說。易中凡言“終吉”者，皆是初不甚好也。</p></li><li><p>王氏申子曰 ：一矢亡，言中之易也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五在旅卦不取君義，程傳之說是也。古者士大夫出疆則以贄行，而士執雉以相見。射雉而得，是進身而有階之象也。信於友則有譽，獲乎上則有命。</p><p>象曰：終以譽命，上逮也</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>上逮言其譽命聞於上也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>有文明柔順之德，則上下與之逮與能。順承於上，而上與之，為上所逮也。在上而得乎下，為下所上逮也。在旅而上下與之，所以致譽命也。旅者困而未得所安之時也，終以譽命，終當致譽命也。己譽命則非旅也，困而親寡則為旅，不必在外也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏瑗曰 ：六五所謂柔得中乎外而順乎剛者也，柔順中正之德為上九所信，尊顯之命及之也。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>六五有位而上九無位，不必以六五為上九所尊顯也。蓋居高位便是上逮爾，此爻雖不以君位言，而亦主於大夫士之載䞇而獲乎名位者，故曰上逮，言其地望已高也。</p><p>上九：鳥焚其巢，旅人先笑後號啕，喪牛於易，兇</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>上九過剛，處旅之上，離之極，驕而不順，兇之道也。故其象佔如此。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>鳥，飛騰處高者也。上九剛不中而處最高，又離體，其亢可知，故取鳥象。在旅之時，謙降柔和乃可自保，而過剛自高，失其所安，宜矣。巢，鳥所安止，焚其巢，失其所安，無所止也。在離上為焚象。陽剛自處於至高，始快其意，故先笑；既而失安莫與，故號啕。輕易以喪其順德，所以兇也。牛，順物。喪牛於易，謂忽易以失其順也。離火性上為躁易之象。上承“鳥焚其巢”，故更加“旅人”字。不雲“旅人”，則是鳥笑哭也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：上九之視九三尤為剛亢者也。凡物棲高處亢而寄諸危地者，鳥之巢是也。故旅之上取以為象。夫高極必危，離火有焚象也，故曰“鳥焚其巢”。先笑謂喜居物上也，後號啕謂巢焚之故也。夫牛，順物也。旅道以柔順謙下為本，上九喪其至順之德，此所以兇也。</p></li><li><p>徐氏幾曰 ：旅貴柔順中正，三陽爻皆失之，而最亢者上九也。</p></li></ul><p>象曰：以旅在上，其義焚也；喪牛於易，終莫之聞也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>以旅在上而以尊高自處，豈能保其居？其義當有焚巢之事。方以極剛自高為得志而笑，不知喪其順德於躁易，是終莫之聞，謂終不自聞知也。使自覺知，則不至於極而號啕矣。陽剛不中而處極，固有高亢躁動之象，而火復炎上，則又甚焉。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>張子曰 ：以陽極上旅而驕肆者也，失柔順之正，故曰喪牛於易。怒而忤物，雖有兇危，其誰告之？故曰終莫之聞也。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>九三以旅與下，郭氏、王氏、黃氏之說美矣。惟以旅在上，則未有說。蓋以旅之道在上，則視所居之位如寄寓然，其無敬畏之心可知，故曰其義焚也。</p><h3 id="總論" tabindex="-1">總論 <a class="header-anchor" href="#總論" aria-label="Permalink to “總論”">​</a></h3><ul><li>範氏仲淹曰：內止而不動於心，外明而弗迷其往，以斯適旅，故得小亨而貞吉。夫旅人之志，卑則自辱，高則見疾，能執其中，可謂智矣。故初瑣瑣，卑以自辱者也；三焚次而上焚巢，高而見疾者也；二懷資而五譽命，柔而不失其中者也。</li></ul>',125)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
